package Test {
  /** in and out as parameter directions next to names that start with the words. */
  port def Api {
    provides operation convert(in input: int, out output: int);
  }
  operation def scale(in inner: int, out outer: int) {
    outer = inner * 2;
  }
  operation def swap(in 'in': int, out 'out': int) {
    'out' = 'in' + 100;
  }
  component def Converter {
    port api: Api;
    attribute inbox: int = 0;
    operation convert(in input: int, out output: int) {
      output = input + 10;
      inbox = input;
    }
    schedule { on call api.convert(input, output) convert(input, output); }
  }
  component def Client {
    reversed port api: Api;
    attribute instate: int = 0;
    attribute outcome: int = 0;
    attribute viewport: bool = false;
    attribute states: int = 0;
    operation run() {
      var outer: int = 0;
      scale(3, outer);
      var in_x: int = 0;
      swap(outer, in_x);
      instate = in_x + outer;
      var received: int = 0;
      api.convert(5, received);
      outcome = received;
      viewport = outcome > 0;
      for (input: int in [1, 2, 3]) {
        states = states + input;
      }
    }
    schedule { on start run(); }
  }
  component Demo {
    component client: Client;
    component converter: Converter;
    connect (client.api, converter.api);
  }
}

package Test {
  /** state as the state keyword next to quoted and unquoted names of states, attributes and transitions. */
  port def Door {
    provides event opened(level: int);
    provides attribute 'state': int;
  }
  component def Panel {
    port door: Door;
    operation run() {
      publish door.opened(1);
      wait 1ms;
      publish door.opened(2);
      send door.'state'(7);
    }
    schedule { on start run(); }
  }
  component def Lock {
    reversed port door: Door;
    attribute 'state': int = 0;
    attribute stateCount: int = 0;
    attribute latest: int = 0;
    operation machine() {
      initial locked;
      state locked {
        on entry { 'state' = 1; stateCount = stateCount + 1; }
        on receive door.opened(level) when (level > 0) to unlocked { 'state' = level; }
      }
      state unlocked {
        on entry { stateCount = stateCount + 1; }
        on receive door.opened(level) to 'final state' { 'state' = 'state' + level; }
      }
      final state 'final state' {
        on entry { stateCount = stateCount + 1; }
      }
    }
    operation keep(value: int) { latest = value; }
    schedule { on start machine(); on receive door.'state'(value) keep(value); }
  }
  component Demo {
    component panel: Panel;
    component lock: Lock;
    connect (panel.door, lock.door);
  }
}

package Test {
  /** view as the view keyword next to quoted view names and filter operands that spell the words. */
  import Swaml::Views;
  component def Part {
    attribute 'in': int = 1;
    attribute 'out': int = 2;
  }
  component Demo {
    component 'state': Part;
    component 'view': Part;
    component inner: Part;
  }
  view 'view': General of Demo;
  view 'state': General {
    include Demo recursive where name == "state" or name == "view";
  }
  view 'in': General {
    include Demo recursive where not (path == "Test::Demo.inner") and kind != "port";
  }
  view viewer: General of Demo.'view';
}

package Test {
  /** for-each loops whose element names and collections are quoted contextual words. */
  enum Mode { 'in', 'out', 'view', 'state' }
  datatype Pair { 'in': int; 'out': int; 'view': Mode; }
  component def Loop {
    attribute 'in': int[3] = [1, 2, 3];
    attribute total: int = 0;
    attribute pairs: Pair[2] = [record Pair { 'in' = 1; 'out' = 2; 'view' = Mode.'in'; }, record Pair { 'in' = 3; 'out' = 4; 'view' = Mode.'state'; }];
    attribute mode: Mode = Mode.'out';
    operation run() {
      for ('out': int in 'in') {
        total = total + 'out';
      }
      for (p: Pair in pairs) {
        total = total + p.'in' * 10 + p.'out' * 100;
        if (p.'view' == Mode.'state') {
          mode = p.'view';
        }
      }
      for (index: int in ['in'[0], 'in'[2]]) {
        total = total + index;
      }
    }
    schedule { on start run(); }
  }
  component Demo: Loop;
}

package 'state'::'view' {
  /** Package names and qualified references made of quoted contextual words. */
  datatype 'in' { 'out': int; }
  operation def 'state'(value: 'in') returns int {
    return value.'out' + 1;
  }
  component def 'out' {
    attribute 'view': 'in' = record 'in' { 'out' = 4; };
    attribute result: int = 0;
    operation run() {
      result = 'state'::'view'::'state'('view');
    }
    schedule { on start run(); }
  }
  component Demo: 'out';
}

package Test {
  /** if statements with else blocks, nested if in else, parenthesized conditions and calls next to them. */
  component def Branches {
    attribute a: int = 0;
    attribute b: int = 0;
    attribute calls: int = 0;
    operation count() returns bool {
      calls = calls + 1;
      return true;
    }
    operation run() {
      if ((a == 0)) {
        a = 1;
      } else {
        a = 2;
      }
      if (a > 5) {
        b = 1;
      } else {
        if (a > 0) {
          b = 2;
        } else {
          b = 3;
        }
      }
      var ok: bool = count();
      if (ok and (b == 2 or calls > 9)) {
        b = b + 10;
      }
      if (not ok) {
        b = -1;
      }
    }
    schedule { on start run(); }
  }
  component Demo: Branches;
}

package Shop {
  /** Single associations, including a repeat with the same spelling and one with another spelling of the same occurrence. */
  port def Till { provides event paid(amount: int); }
  component def Register {
    reversed port till: Till;
    attribute total: int = 0;
    operation take(amount: int) { total = total + amount; }
    schedule { on receive till.paid(amount) take(amount); }
  }
  component def Customer { port till: Till; }
  component register: Register;
  component customer: Customer;
  component other: Customer;
  connect (customer.till, register.till);
  use case 'Pay at till' of register {
    publish customer.till.paid(5);
    wait 1ms;
  }
  test 'Totals add up' of register {
    publish customer.till.paid(5);
    wait 1ms;
    assert register.total == 5;
  }
  associate customer to 'Pay at till';
  associate customer to 'Pay at till';
  associate customer to 'Totals add up';
  associate 'customer' to 'Totals add up';
  associate other to 'Pay at till';
}

