package Test {
  /** Duplicate single associations with the same spelling report the 2.2 message; an unknown case is unresolved. */
  component def C { }
  component a: C;
  component b: C;
  use case X of a { }
  use case Y of a { }
  associate b to X;
  associate b to Y;
  associate b to X;
  associate b to Z;
}

package Test {
  /** Type errors next to if statements keep their 2.2 messages. */
  component def Bad {
    attribute a: int = 0;
    operation g() returns int { return 1; }
    operation run() {
      if (a) {
        a = 1;
      } else {
        a = 2;
      }
      if (g() + 1) {
        a = 3;
      }
      var b: bool = 1;
      a = true;
    }
    schedule { on start run(); }
  }
  component Demo: Bad;
}

package Test {
  /** Suspending calls in expressions keep the 2.2 message. */
  port def Api { provides operation get() returns int; }
  component def Server {
    port api: Api;
    operation get() returns int { return 3; }
    schedule { on call api.get() get(); }
  }
  component def Client {
    reversed port api: Api;
    attribute x: int = 0;
    operation run() {
      x = api.get() + 1;
      if (api.get() > 0) {
        x = 2;
      }
      var y: int = api.get();
      x = y;
    }
    schedule { on start run(); }
  }
  component Demo {
    component client: Client;
    component server: Server;
    connect (client.api, server.api);
  }
}

package Test {
  /** Ports, members and endpoints with quoted contextual words, used by publish, send, calls and receive. */
  port def 'view' {
    provides event 'state'(value: int);
    provides operation 'in'(value: int) returns int;
    provides attribute 'out': int;
  }
  component def Provider {
    port 'in': 'view';
    attribute served: int = 0;
    operation answer(value: int) returns int { served = served + 1; return value * 3; }
    operation run() {
      publish 'in'.'state'(4);
      send 'in'.'out'(9);
    }
    schedule { on start run(); on call 'in'.'in'(value) answer(value); }
  }
  component def Consumer {
    reversed port 'out': 'view';
    attribute got: int = 0;
    attribute level: int = 0;
    attribute reply: int = 0;
    operation take(value: int) { got = value; }
    operation keep(value: int) { level = value; }
    operation ask() { reply = 'out'.'in'(5); }
    schedule { on receive 'out'.'state'(value) take(value); on receive 'out'.'out'(value) keep(value); on start ask(); }
  }
  component Demo {
    component provider: Provider;
    component consumer: Consumer;
    connect (provider.'in', consumer.'out');
  }
}

package Test {
  /** A test reads quoted contextual-word attributes of its subject and an associated root. */
  component def Session {
    attribute 'state': int = 0;
    attribute 'view': bool = false;
    operation run() { 'state' = 2; 'view' = true; }
    operation 'in'() returns int { return 'state' + 1; }
    schedule { on start run(); }
  }
  component def App { component 'out': Session; }
  component app: App;
  component helper: Session;
  test 'Reads the state' of app {
    wait 1ms;
    assert app.'out'.'state' == 2 and app.'out'.'view';
    var 'in': int = app.'out'.'in'();
    assert 'in' == 3;
    assert helper.'state' == 2;
  }
  associate helper to 'Reads the state';
}

package Test {
  /** A test with on call out bindings of an operation with in and out parameters. */
  port def Desk { requires operation lookup(in key: int, out value: int); provides event viewed(key: int); }
  component def Clerk {
    port desk: Desk;
    attribute outValue: int = 0;
    operation run() {
      var v: int = 0;
      desk.lookup(4, v);
      outValue = v;
      publish desk.viewed(v);
    }
    schedule { on start run(); }
  }
  component def Archive { reversed port desk: Desk; }
  component clerk: Clerk;
  component archive: Archive;
  connect (clerk.desk, archive.desk);
  test 'Lookup answers' of clerk {
    on call archive.desk.lookup(key, value) {
      value = key * 2;
    }
    on receive archive.desk.viewed(key) {
      assert key == 8;
    }
    assert clerk.outValue == 8;
  }
  associate archive to 'Lookup answers';
}

package Test {
  /** Stale reads and writes across waits in if branches keep the 2.2 SW2011 findings. */
  component def Timed {
    attribute level: int = 0;
    attribute stored: int = 0;
    operation bump() { level = level + 1; }
    operation run() {
      var copy: int = level;
      if (copy > 0) {
        wait 1ms;
      } else {
        wait 2ms;
      }
      level = copy + 1;
      stored = level;
    }
    schedule { on start run(); on every 1ms bump(); }
  }
  component Demo: Timed;
}

package A {
  component def 'operation' { }
  component def inbound { }
}
package B {
  component def 'operation' { }
  component def inbound { }
}
package Test {
  import A;
  import B;
  component x: 'operation';
  component y: inbound;
}

package Test {
  /** Basic names that begin with view, state, in, out and if stay names. */
  enum states { inbound, outbound, viewing }
  datatype views { input: int; output: int; ifValue: int; elsewhere: bool; }
  component def outer {
    attribute instance: views = record views { input = 1; output = 2; ifValue = 3; elsewhere = true; };
    attribute stateNow: states = states.inbound;
    attribute inner_out: int = 0;
    operation viewAll(inValue: int, outValue: int) returns int { return inValue + outValue; }
    operation run() {
      inner_out = viewAll(instance.input, instance.output) + instance.ifValue;
      if (instance.elsewhere) {
        stateNow = states.viewing;
      }
    }
    schedule { on start run(); }
  }
  component Demo: outer;
}
